def max_value_on_paths(N, grid_values):
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the values from the input list
    for x, y, value in grid_values:
        grid[x][y] = value

    # Fill the first row and first column with the values from the first row and first column of the grid
    for i in range(1, N):
        grid[0][i] += grid[0][i-1]
        grid[i][0] += grid[i-1][0]

    # Fill the rest of the grid using dynamic programming
    for i in range(1, N):
        for j in range(1, N):
            grid[i][j] += max(grid[i-1][j], grid[i][j-1])

    # The maximum value on the bottom-right corner of the grid is the answer
    return grid[N-1][N-1]

def sum_of_factorials_optimized(n: int) -> int:
    if not (1 <= n <= 50):
        raise ValueError("n must be in the range of 1 to 50, inclusive.")

    factorial_sum = 0
    current_factorial = 1

    for i in range(1, n + 1):
        factorial_sum += current_factorial
        current_factorial *= i

    return factorial_sum

def cantor_numbering(N: int) -> str:
    if N == 0:
        return "0/1"

    numerator = 1
    denominator = N + 1

    while N > 1:
        if N % 2 == 0:
            numerator, denominator = denominator, numerator
        N //= 2

    return f"{numerator}/{denominator}"

