def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        return "Invalid ISBN length"

    # Remove the hyphen if present
    isbn = isbn.replace('-', '')

    # Check if the first 12 characters are digits
    if not isbn[:12].isdigit():
        return "Invalid ISBN format"

    # Calculate the checksum
    sum = 0
    for i in range(12):
        if i % 2 == 0:
            sum += int(isbn[i])
        else:
            sum += int(isbn[i]) * 3

    # Calculate the check digit
    check_digit = 10 - (sum % 10)
    if check_digit == 10:
        check_digit = 0

    # Check if the calculated check digit matches the last character
    if check_digit != int(isbn[12]):
        return isbn
    else:
        return "Right"

def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D array to store the number of ways to pass the ball
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one way to pass the ball to the right neighbor from the starting student
    for i in range(1, n + 1):
        dp[i][1] = 1

    # Fill the dp array using dynamic programming
    for i in range(2, n + 1):
        for j in range(2, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    # The result is the number of ways to pass the ball to the right neighbor from the starting student after m passes
    return dp[n][m]

