def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store the maximum value for each time and herb
    dp = [[0] * (M + 1) for _ in range(T + 1)]

    # Iterate over each time and herb
    for time, value in herbs:
        # Update the dp array for each time and herb
        for i in range(T, time - 1, -1):
            for j in range(M, 0, -1):
                dp[i][j] = max(dp[i][j], dp[i - time][j - 1] + value)

    # The maximum value that can be picked within the time limit
    return dp[T][M]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Create a 2D array to store the maximum volume that can be occupied
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    min_remaining = V - dp[n][V]

    return min_remaining

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        for j in range(m, a[i] - 1, -1):
            dp[j] = (dp[j] + dp[j - a[i]]) % MOD

    return dp[m]

def mod_inverse(a, b):
    if b == 0:
        return None
    x, y, u, v = 0, 1, 1, 0
    while b:
        q = a // b
        a, b = b, a % b
        x, u = u, x - q * u
        y, v = v, y - q * v
    return x % b

def find_most_unhappy_day(schedule) -> int:
    total_hours = sum(hours for hours, _ in schedule)
    threshold = 8
    max_unhappiness = 0
    most_unhappy_day = 0

    for day, hours in enumerate(schedule):
        if hours > threshold:
            unhappiness = hours - threshold
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day + 1

    return most_unhappy_day if max_unhappiness > 0 else 0

